<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $user = \App\Models\User::first(); $controller = $app->make(\App\Modules\AI\Controllers\ChatController::class); $request = \Illuminate\Http\Request::create('/api/v1/ai/chat', 'POST', ['messages' => [['role' => 'user', 'content' => 'What is 12345.67 * 8901.23 / 3.14? Please strictly use the calculate tool for this exact arithmetic.']]]); $request->setUserResolver(function () use ($user) { return $user; }); $response = $controller->chat($request); echo $response->getContent();
